/* =================== CHAPTER I — ACT II: VESPERIA, CITY OF CANDLES =================== */
SC.a2_title = {bg:"road", loc:LOC.greyroad,
  t:["ATTO II — VESPERIA, LA CITTÀ DELLE CANDELE\n\nTre giorni di cammino nel buio lungo la Strada Grigia. Dormite a turno, le armi in mano. Il marchio sulla tua mano pulsa più forte a ogni miglio che vi avvicina a Vesperia.",
     "ACT II — VESPERIA, CITY OF CANDLES\n\nThree days' march in the dark along the Grey Road. You sleep in shifts, weapons in hand. The mark on your hand throbs harder with every mile that brings you closer to Vesperia.",
     "ACTO II — VESPERIA, LA CIUDAD DE LAS VELAS\n\nTres días de marcha en la oscuridad por el Camino Gris. Dormís por turnos, con las armas en la mano. La marca de tu mano late con más fuerza a cada legua que os acerca a Vesperia."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_bridge"}]};

SC.a2_bridge = {bg:"bridge", loc:LOC.greyroad,
  t:["Al Ponte del Pianto, un arco di pietra sopra un fiume nero, una barricata di carri sbarra la strada. Una mezza dozzina di banditi, con torce e balestre. La loro capa, una donna con una benda sull'occhio, sorride.\n\n«Pedaggio. Trenta monete a testa… no, facciamo trenta in tutto. Sono generosa, coi tempi che corrono.»",
     "At the Weeping Bridge, a stone arch over a black river, a barricade of wagons blocks the road. Half a dozen bandits with torches and crossbows. Their leader, a woman with an eyepatch, smiles.\n\n“Toll. Thirty coins a head… no, call it thirty in all. I'm generous, times being what they are.”",
     "En el Puente del Llanto, un arco de piedra sobre un río negro, una barricada de carros corta el camino. Media docena de bandidos con antorchas y ballestas. Su jefa, una mujer con un parche en el ojo, sonríe.\n\n«Peaje. Treinta monedas por cabeza… no, digamos treinta en total. Soy generosa, con los tiempos que corren.»"],
  ch:[
    {t:["Pagare il pedaggio","Pay the toll","Pagar el peaje"], cost:30, go:"a2_bridge_paid"},
    {t:["Raccontarle di Ashford e del Sole Nero","Tell her about Ashford and the Black Sun","Contarle lo de Ashford y el Sol Negro"], check:{sk:"pers", dc:13, ok:"a2_bridge_talk", ko:"a2_bridge_fight"}},
    {t:["Mostrare il marchio e minacciarla","Show the mark and threaten her","Mostrar la marca y amenazarla"], check:{sk:"inti", dc:14, ok:"a2_bridge_flee", ko:"a2_bridge_fight"}},
    {t:["Attaccare","Attack","Atacar"], fight:"bandits", win:"a2_bridge_won"}]};

SC.a2_bridge_paid = {bg:"bridge", loc:LOC.greyroad,
  t:["La capobanda conta le monete e si scansa. «Buon viaggio. Occhio alle ombre più avanti: quelle non accettano pedaggi.»","The leader counts the coins and steps aside. “Safe travels. Watch the shadows further on: they don't take tolls.”","La jefa cuenta las monedas y se aparta. «Buen viaje. Cuidado con las sombras más adelante: esas no cobran peaje.»"],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_caravan"}]};
SC.a2_bridge_talk = {bg:"bridge", loc:LOC.greyroad, once(){ set("mira_ally"); xp(300); },
  t:["Le racconti di Ashford, dei bambini nelle gabbie, del Sole Nero. Lei ascolta senza interromperti. Alla fine sospira.\n\n«Ero una guardia di Vesperia, prima che il Duca vendesse la città al buio. Passate. E se qualcuno vi chiede chi combatte il Duca, dite che Mira Benda c'è.»",
     "You tell her about Ashford, the children in cages, the Black Sun. She listens without interrupting. In the end she sighs.\n\n“I was a Vesperia guard, before the Duke sold the city to the dark. Go on through. And if anyone asks who fights the Duke, tell them Mira Patch is in.”",
     "Le hablas de Ashford, de los niños en jaulas, del Sol Negro. Escucha sin interrumpir. Al final suspira.\n\n«Era guardia de Vesperia, antes de que el Duque vendiera la ciudad a la oscuridad. Pasad. Y si alguien pregunta quién lucha contra el Duque, decid que Mira Parche está dentro.»"],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_caravan"}]};
SC.a2_bridge_flee = {bg:"bridge", loc:LOC.greyroad, once(){ xp(200); },
  t:["Sollevi la mano: il marchio pulsa di luce nera nel buio. I banditi si guardano tra loro, poi fuggono nella notte. «Un marchiato! Porta sfortuna!» Perfino la loro capa indietreggia, imprecando.","You raise your hand: the mark pulses with black light in the dark. The bandits glance at one another, then flee into the night. “A marked one! Bad luck!” Even their leader backs off, cursing.","Alzas la mano: la marca late con luz negra en la oscuridad. Los bandidos se miran entre sí y huyen en la noche. «¡Un marcado! ¡Trae mala suerte!» Hasta su jefa retrocede, maldiciendo."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_caravan"}]};
SC.a2_bridge_fight = {bg:"bridge", loc:LOC.greyroad,
  t:["«Peccato» dice la donna, e alza la balestra.","“Pity,” says the woman, and raises her crossbow.","«Lástima» dice la mujer, y alza la ballesta."],
  ch:[{t:["Combattere!","Fight!","¡Luchar!"], fight:"bandits", win:"a2_bridge_won"}]};
SC.a2_bridge_won = {bg:"bridge", loc:LOC.greyroad, once(){ gold(40); },
  t:["La capobanda getta la spada, ferita. «Basta! Ero una guardia, io. Il Duca ci ha cacciati quando ci siamo rifiutati di accendere le sue lanterne nere.» La lasciate andare e raccogliete il bottino della barricata.","The leader throws down her sword, wounded. “Enough! I was a guard. The Duke threw us out when we refused to light his black lanterns.” You let her go and gather the barricade's loot.","La jefa arroja la espada, herida. «¡Basta! Yo era guardia. El Duque nos echó cuando nos negamos a encender sus linternas negras.» La dejáis ir y recogéis el botín de la barricada."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_caravan"}]};

SC.a2_caravan = {bg:"road", loc:LOC.greyroad,
  t:["Più avanti, una carovana rovesciata. Una mercante halfling e i suoi due nipoti sono rintanati sotto un carro, mentre forme d'ombra senza volto graffiano il legno.","Further on, an overturned caravan. A halfling merchant and her two nephews cower under a wagon while faceless shapes of shadow claw at the wood.","Más adelante, una caravana volcada. Una mercader mediana y sus dos sobrinos se esconden bajo un carro mientras formas de sombra sin rostro arañan la madera."],
  ch:[{t:["Aiutarli","Help them","Ayudarlos"], fight:"shadows", win:"a2_caravan_won"},{t:["Proseguire senza fermarsi","Keep going","Seguir sin detenerse"], go:"a2_gate"}]};
SC.a2_caravan_won = {bg:"road", loc:LOC.greyroad, once(){ set("pia"); gold(25); xp(100); },
  t:["La mercante, Pia Tondafoglia, vi abbraccia le ginocchia. «Ho un banco al Mercato delle Candele di Vesperia. Per voi, prezzi da amici. Per sempre!»","The merchant, Pia Roundleaf, hugs your knees. “I have a stall at the Candle Market in Vesperia. For you, friends' prices. Forever!”","La mercader, Pia Hojarredonda, os abraza las rodillas. «Tengo un puesto en el Mercado de las Velas de Vesperia. Para vosotros, precios de amigo. ¡Para siempre!»"],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"a2_gate"}]};

SC.a2_gate = {bg:"city", loc:LOC.vesperia,
  t:["Vesperia appare all'improvviso: una città di torri e ponti, illuminata da migliaia di lanterne che ardono di una fiamma viola. Niente fumo, niente calore. Solo una luce fredda che fa sembrare tutti malati.\n\nAlla porta, un capitano della guardia vi sbarra il passo. «Nessuno entra senza documenti. Ordine del Duca Malvern.»",
     "Vesperia appears all at once: a city of towers and bridges, lit by thousands of lanterns burning with a violet flame. No smoke, no warmth. Only a cold light that makes everyone look sick.\n\nAt the gate, a guard captain bars your way. “Nobody enters without papers. Duke Malvern's orders.”",
     "Vesperia aparece de golpe: una ciudad de torres y puentes, iluminada por miles de linternas que arden con una llama violeta. Sin humo, sin calor. Solo una luz fría que hace que todos parezcan enfermos.\n\nEn la puerta, un capitán de la guardia os cierra el paso. «Nadie entra sin documentos. Órdenes del Duque Malvern.»"],
  ch:[{t:["Mostrare la lettera di Seraphine","Show Seraphine's letter","Mostrar la carta de Seraphine"], go:"a2_gate2"}]};
SC.a2_gate2 = {bg:"city", loc:LOC.vesperia, once(){ take("letter"); },
  t:["Il capitano rompe il sigillo, legge, e impallidisce. Poi fa una cosa strana: si tocca la fronte con due dita, come in un gesto di riverenza.\n\n«Passate. Benvenuti a Vesperia.»","The captain breaks the seal, reads, and turns pale. Then he does something odd: he touches two fingers to his forehead, like a gesture of reverence.\n\n“Go through. Welcome to Vesperia.”","El capitán rompe el sello, lee y palidece. Luego hace algo extraño: se toca la frente con dos dedos, como en un gesto de reverencia.\n\n«Pasad. Bienvenidos a Vesperia.»"],
  ch:[
    {t:["Ripensare a quel gesto","Think about that gesture","Pensar en ese gesto"], req:()=>!has("gate_ins"), check:{sk:"ins", dc:12, ok:"a2_gate_sus", ko:"a2_gate_none"}},
    {t:["Entrare in città","Enter the city","Entrar en la ciudad"], go:"vesperia"}]};
SC.a2_gate_sus = {bg:"city", loc:LOC.vesperia, once(){ set("gate_ins"); set("sus_ser2"); xp(75); },
  t:["Hai già visto quel gesto: due dita sulla fronte. Lo faceva Varga, sulla collina, prima di alzare il pugnale. È il saluto della Corona Cava.\n\nE la lettera era di Seraphine.","You've seen that gesture before: two fingers to the forehead. Varga did it on the hill, before raising his dagger. It's the salute of the Hollow Crown.\n\nAnd the letter was Seraphine's.","Ya has visto ese gesto: dos dedos en la frente. Lo hacía Varga en la colina, antes de alzar la daga. Es el saludo de la Corona Hueca.\n\nY la carta era de Seraphine."],
  ch:[{t:["Entrare in città","Enter the city","Entrar en la ciudad"], go:"vesperia"}]};
SC.a2_gate_none = {bg:"city", loc:LOC.vesperia, once(){ set("gate_ins"); },
  t:["Forse è un'usanza locale. Vesperia è una città strana.","Perhaps it's a local custom. Vesperia is a strange city.","Quizá sea una costumbre local. Vesperia es una ciudad extraña."],
  ch:[{t:["Entrare in città","Enter the city","Entrar en la ciudad"], go:"vesperia"}]};

SC.vesperia = {bg:"city", loc:LOC.vesperia, hub:1,
  t:()=>cat(["Vesperia. Le lanterne viola ronzano come insetti sopra le strade. La gente cammina a testa bassa, e molti hanno lo sguardo vuoto di chi ha dimenticato qualcosa di importante.","Vesperia. The violet lanterns hum like insects above the streets. People walk with their heads down, and many have the empty look of someone who has forgotten something important.","Vesperia. Las linternas violetas zumban como insectos sobre las calles. La gente camina cabizbaja, y muchos tienen la mirada vacía de quien ha olvidado algo importante."],
    has("lamps_freed") && ["Dove prima ardevano le lanterne nere ora tremolano candele vere. La gente ricorda, e piange, e ride.","Where the black lanterns burned, real candles now flicker. People remember, and weep, and laugh.","Donde ardían las linternas negras ahora titilan velas de verdad. La gente recuerda, y llora, y ríe."],
    has("took_flame") && ["Le lanterne viola sono spente, ma i ricordi non sono tornati. La città è più buia e più muta di prima.","The violet lanterns are dark, but the memories have not returned. The city is darker and quieter than before.","Las linternas violetas están apagadas, pero los recuerdos no han vuelto. La ciudad está más oscura y callada que antes."],
    has("act2_done") && ["Dopo la morte di Pellin, l'Archivio è chiuso. A nord, oltre i tetti, una colonna di buio sale dal picco della Corona di Cenere.","Since Pellin's death, the Archive is closed. To the north, beyond the rooftops, a column of darkness rises from the peak of the Crown of Ash.","Tras la muerte de Pellin, el Archivo está cerrado. Al norte, más allá de los tejados, una columna de oscuridad se alza desde el pico de la Corona de Ceniza."]),
  ch:[
    {t:["Il Grande Archivio","The Great Archive","El Gran Archivo"], req:()=>!has("act2_done"), go:()=>has("has_key") ? "a2_betrayal" : "a2_archive"},
    {t:["Taverna «Il Ratto Annegato»","“The Drowned Rat” tavern","Taberna «La Rata Ahogada»"], go:"a2_rat"},
    {t:["Mercato delle Candele","Candle Market","Mercado de las Velas"], shop:"vesperia"},
    {t:["La Torre della Lanterna","The Lantern Tower","La Torre de la Linterna"], req:()=>has("q_tower") && !has("tower_done"), go:"a2_tower"},
    {t:["La Torre Campanaria, al nono rintocco","The Bell Tower, at the ninth bell","El Campanario, a la novena campanada"], req:()=>has("q_doran") && !has("doran_done") && inP("kael"), go:"a2_bell"},
    {t:["Il ballo in maschera del Duca","The Duke's masquerade","El baile de máscaras del Duque"], req:()=>has("invite") && !has("masq_done"), go:"a2_masq"},
    {t:["Le fogne della Città Bassa","The Lower City sewers","Las cloacas de la Ciudad Baja"], req:()=>has("q_key") && !has("has_key"), go:"a2_sewers"},
    {t:["Le Volte di Aurel, sotto la cappella dell'Archivio","The Vaults of Aurel, beneath the Archive chapel","Las Bóvedas de Aurel, bajo la capilla del Archivo"], req:()=>has("vault_known") && !has("vault_done"), go:"v_enter"},
    {t:["Riposare alla locanda","Rest at the inn","Descansar en la posada"], cost:10, rest:1},
    {t:["Partire per la Corona di Cenere","Set out for the Crown of Ash","Partir hacia la Corona de Ceniza"], req:()=>has("act2_done"), go:"a3_title"}]};

SC.a2_archive = {bg:"archive", loc:LOC.archive,
  t:()=> has("met_pellin") ?
    ["Pellin solleva gli occhi dai suoi registri. «Ancora qui? Le fogne della Città Bassa sono l'unica via per l'Archivio Sommerso. Fate presto.»","Pellin looks up from his ledgers. “Still here? The Lower City sewers are the only way into the Drowned Archive. Hurry.”","Pellin levanta la vista de sus registros. «¿Todavía aquí? Las cloacas de la Ciudad Baja son el único camino al Archivo Sumergido. Daos prisa.»"] :
    ["Il Grande Archivio di Vesperia è una cattedrale di libri. Scaffali alti come alberi si perdono nel buio. Un vecchio gnomo con le dita sporche d'inchiostro e occhiali spessi come fondi di bottiglia vi viene incontro.\n\n«Pellin, archivista capo. Cosa… oh. Oh, cielo. Un marchiato.»","The Great Archive of Vesperia is a cathedral of books. Shelves tall as trees vanish into the dark. An old gnome with ink-stained fingers and spectacles thick as bottle bottoms comes to meet you.\n\n“Pellin, head archivist. What… oh. Oh, my. A marked one.”","El Gran Archivo de Vesperia es una catedral de libros. Estanterías altas como árboles se pierden en la oscuridad. Un viejo gnomo de dedos manchados de tinta y gafas gruesas como culos de botella sale a vuestro encuentro.\n\n«Pellin, archivero jefe. ¿Qué… oh. Oh, cielos. Un marcado.»"],
  enter(){ set("met_pellin"); },
  ch:[
    {t:["«Cerchiamo la Chiave dell'Alba.»","“We're looking for the Key of Dawn.”","«Buscamos la Llave del Alba.»"], req:()=>!has("q_key"), go:"a2_pellin_key"},
    {t:["«Parlaci dei Custodi del Sole.»","“Tell us about the Sunwardens.”","«Háblanos de los Custodios del Sol.»"], req:()=>!has("pl_lore"), go:"a2_pellin_lore"},
    {t:["«Conosci un certo Mortimer?»","“Do you know a certain Mortimer?”","«¿Conoces a un tal Mortimer?»"], req:()=>!has("pl_mort"), go:"a2_pellin_mort"},
    {t:["«Che cosa c'è sotto la cappella dell'Archivio?»","“What lies beneath the Archive chapel?”","«¿Qué hay bajo la capilla del Archivo?»"], req:()=>!has("vault_known") && !has("act2_done"), go:"v_pellin"},
    {t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};

SC.a2_pellin_key = {bg:"archive", loc:LOC.archive, once(){ set("q_key"); toastQ(["Nuova missione: La Chiave dell'Alba","New quest: The Key of Dawn","Nueva misión: La Llave del Alba"]); },
  t:["Pellin si toglie gli occhiali e li pulisce, nervoso. «La Chiave dell'Alba è custodita nella cripta più profonda dell'Archivio, sotto il livello del fiume. Due settimane fa uomini incappucciati hanno sfondato le chiuse: l'acqua ha invaso tutto. Ora i piani inferiori li chiamiamo l'Archivio Sommerso. Ci sono… cose, là sotto.»\n\nAbbassa la voce. «E c'è una persona. Ilyra, una studiosa elfica. Aveva capito cosa stava succedendo al sole. Il Duca l'ha fatta rinchiudere laggiù, per farla tacere, poco prima dell'inondazione. Se è viva, è un miracolo.»\n\nVi porge una mappa. «L'unico accesso rimasto passa dalle fogne della Città Bassa.»",
     "Pellin takes off his spectacles and polishes them nervously. “The Key of Dawn is kept in the deepest crypt of the Archive, below the river line. Two weeks ago hooded men smashed the sluices: the water flooded everything. Now we call the lower floors the Drowned Archive. There are… things, down there.”\n\nHe lowers his voice. “And there is a person. Ilyra, an elven scholar. She had worked out what was happening to the sun. The Duke had her locked down there to silence her, just before the flood. If she's alive, it's a miracle.”\n\nHe hands you a map. “The only way left in is through the Lower City sewers.”",
     "Pellin se quita las gafas y las limpia, nervioso. «La Llave del Alba se guarda en la cripta más profunda del Archivo, bajo el nivel del río. Hace dos semanas unos encapuchados reventaron las compuertas: el agua lo inundó todo. Ahora llamamos a los pisos inferiores el Archivo Sumergido. Hay… cosas, ahí abajo.»\n\nBaja la voz. «Y hay una persona. Ilyra, una erudita elfa. Había entendido lo que le pasaba al sol. El Duque la hizo encerrar allí abajo para silenciarla, poco antes de la inundación. Si está viva, es un milagro.»\n\nOs tiende un mapa. «El único acceso que queda pasa por las cloacas de la Ciudad Baja.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_archive"}]};
SC.a2_pellin_lore = {bg:"archive", loc:LOC.archive, once(){ set("pl_lore"); set("lore2"); xp(25); },
  t:["«Mille anni fa Morrhan, il Dio Affamato, divorò tre regni. I Custodi del Sole lo incatenarono nell'ombra della luna e chiusero la catena con la luce stessa del sole. Finché il sole brilla, Morrhan dorme.»\n\nSi gratta la barba. «Ma se il sole si spegne, la catena si allenta. E quaranta giorni fa qualcuno ha spento il sole.»",
     "“A thousand years ago Morrhan, the Hungering God, devoured three kingdoms. The Sunwardens chained him in the shadow of the moon and locked the chain with the very light of the sun. While the sun shines, Morrhan sleeps.”\n\nHe scratches his beard. “But if the sun goes out, the chain loosens. And forty days ago, someone put out the sun.”",
     "«Hace mil años Morrhan, el Dios Hambriento, devoró tres reinos. Los Custodios del Sol lo encadenaron en la sombra de la luna y cerraron la cadena con la luz misma del sol. Mientras el sol brille, Morrhan duerme.»\n\nSe rasca la barba. «Pero si el sol se apaga, la cadena se afloja. Y hace cuarenta días alguien apagó el sol.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_archive"}]};
SC.a2_pellin_mort = {bg:"archive", loc:LOC.archive, once(){ set("pl_mort"); set("sus_mort"); },
  t:["Pellin sbatte le palpebre. «Mortimer? Il cancelliere? È morto di febbre l'inverno scorso. Ho scritto io il necrologio.» Vi guarda incuriosito. «Perché?»","Pellin blinks. “Mortimer? The chancellor? He died of fever last winter. I wrote his obituary myself.” He looks at you curiously. “Why?”","Pellin parpadea. «¿Mortimer? ¿El canciller? Murió de fiebres el invierno pasado. Yo mismo escribí su necrológica.» Os mira con curiosidad. «¿Por qué?»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_archive"}]};

SC.a2_rat = {bg:"tavern2", loc:LOC.rat,
  t:()=>cat(["Il Ratto Annegato è una bettola sotto un ponte, piena di fumo e di gente che non vuole essere riconosciuta. Dietro il bancone, una donna magra vestita di seta nera gioca con un coltello: Silk, padrona della Gilda delle Ombre.","The Drowned Rat is a dive under a bridge, full of smoke and people who don't want to be recognised. Behind the bar, a thin woman in black silk toys with a knife: Silk, mistress of the Shadow Guild.","La Rata Ahogada es un antro bajo un puente, lleno de humo y de gente que no quiere ser reconocida. Tras la barra, una mujer delgada vestida de seda negra juega con un cuchillo: Silk, señora del Gremio de las Sombras."],
    inP("kael") && !has("silk_met") && ["Quando vede Kael, il coltello si ferma. «Kael Varn. Il figliol prodigo. Ti credevo morto.» «Ci ho provato» risponde lui. «Non mi è riuscito.»","When she sees Kael, the knife stops. “Kael Varn. The prodigal son. I thought you were dead.” “I tried,” he answers. “Didn't take.”","Cuando ve a Kael, el cuchillo se detiene. «Kael Varn. El hijo pródigo. Te creía muerto.» «Lo intenté» responde él. «No funcionó.»"],
    !inP("kael") && !has("kael_late") && ["In un angolo, con i piedi sul tavolo, c'è un volto che conosci: Kael Varn, il ladro della gogna di Ashford. «Sono scappato da solo, alla fine» ti dice. «Ma da solo è noioso.»","In a corner, feet on the table, sits a face you know: Kael Varn, the thief from Ashford's stocks. “Got out on my own in the end,” he tells you. “But on my own is boring.”","En un rincón, con los pies sobre la mesa, hay una cara que conoces: Kael Varn, el ladrón de la picota de Ashford. «Al final me escapé solo» te dice. «Pero solo es aburrido.»"]),
  enter(){ set("silk_met"); },
  ch:[
    {t:["Invitare Kael a unirsi al gruppo","Invite Kael to join you","Invitar a Kael a unirse al grupo"], req:()=>!inP("kael") && !has("kael_late"), fx(){ set("kael_late"); join("kael"); set("q_doran_hint"); }, go:"a2_rat"},
    {t:["«Ci serve un invito al ballo del Duca.»","“We need an invitation to the Duke's ball.”","«Necesitamos una invitación al baile del Duque.»"], req:()=>!has("q_tower"), go:"a2_silk_job"},
    {t:["Riferire della Torre della Lanterna","Report on the Lantern Tower","Informar sobre la Torre de la Linterna"], req:()=>has("tower_done") && !has("invite"), go:"a2_silk_invite"},
    {t:["«Sai qualcosa di Doran Varn?»","“Do you know anything about Doran Varn?”","«¿Sabes algo de Doran Varn?»"], req:()=>inP("kael") && !has("q_doran"), go:"a2_silk_doran"},
    {t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};

SC.a2_silk_job = {bg:"tavern2", loc:LOC.rat, once(){ set("q_tower"); toastQ(["Nuova missione: La fiamma madre","New quest: The mother flame","Nueva misión: La llama madre"]); },
  t:["Silk sorride. «Tutti vogliono andare al ballo. Il Duca firma patti con il buio e poi balla sopra la città.» Si fa seria. «Le sue lanterne viola non bruciano olio: bruciano ricordi. Ogni notte la gente dimentica un nome, un volto. Tre dei miei hanno dimenticato le proprie madri.»\n\nPianta il coltello nel bancone. «La fiamma madre arde in cima alla Torre della Lanterna. Spegnila, e avrai il tuo invito.»",
     "Silk smiles. “Everyone wants to go to the ball. The Duke signs pacts with the dark and then dances on top of the city.” She turns serious. “His violet lanterns don't burn oil: they burn memories. Every night people forget a name, a face. Three of mine have forgotten their own mothers.”\n\nShe stabs the knife into the bar. “The mother flame burns at the top of the Lantern Tower. Put it out, and you'll have your invitation.”",
     "Silk sonríe. «Todo el mundo quiere ir al baile. El Duque firma pactos con la oscuridad y luego baila sobre la ciudad.» Se pone seria. «Sus linternas violetas no queman aceite: queman recuerdos. Cada noche la gente olvida un nombre, una cara. Tres de los míos han olvidado a sus propias madres.»\n\nClava el cuchillo en la barra. «La llama madre arde en lo alto de la Torre de la Linterna. Apágala, y tendrás tu invitación.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_rat"}]};
SC.a2_silk_invite = {bg:"tavern2", loc:LOC.rat, once(){ set("invite"); toastQ(["Nuova missione: Il ballo in maschera","New quest: The masquerade","Nueva misión: El baile de máscaras"]); },
  t:()=>cat(has("lamps_freed") ?
    ["«Ho sentito. Tutta la città ha sentito: stanotte la gente si è svegliata piangendo, ricordando.»","“I heard. The whole city heard: tonight people woke up weeping, remembering.”","«Lo he oído. Toda la ciudad lo ha oído: esta noche la gente se ha despertado llorando, recordando.»"] :
    ["«Le lanterne sono spente… anche se dicono che la fiamma madre non si sia spenta: è sparita. Non voglio sapere dove.» Ti guarda la mano.","“The lanterns are out… though they say the mother flame didn't go out: it vanished. I don't want to know where.” She looks at your hand.","«Las linternas están apagadas… aunque dicen que la llama madre no se apagó: desapareció. No quiero saber dónde.» Te mira la mano."],
    ["Ti porge un cartoncino nero orlato d'oro e una maschera d'argento. «Il ballo è stanotte. Il Duca tiene un registro dei suoi patti nello studio privato. Se qualcuno lo trovasse e lo leggesse ad alta voce…»","She hands you a black card edged in gold and a silver mask. “The ball is tonight. The Duke keeps a ledger of his pacts in his private study. If someone were to find it and read it aloud…”","Te tiende una tarjeta negra ribeteada en oro y una máscara de plata. «El baile es esta noche. El Duque guarda un registro de sus pactos en su estudio privado. Si alguien lo encontrara y lo leyera en voz alta…»"]),
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_rat"}]};
SC.a2_silk_doran = {bg:"tavern2", loc:LOC.rat, once(){ set("q_doran"); toastQ(["Nuova missione: Il fratello di Kael","New quest: Kael's brother","Nueva misión: El hermano de Kael"]); },
  t:["«Doran. Il fratello buono, quello che non rubava.» Silk guarda Kael. «Indossa la maschera grigia, adesso. Porta messaggi per la Corona Cava. Al nono rintocco sarà alla Torre Campanaria a ritirare un carico.»\n\nKael stringe i pugni. «Ci sarò.»","“Doran. The good brother, the one who didn't steal.” Silk looks at Kael. “He wears the grey mask now. Carries messages for the Hollow Crown. At the ninth bell he'll be at the Bell Tower collecting a shipment.”\n\nKael clenches his fists. “I'll be there.”","«Doran. El hermano bueno, el que no robaba.» Silk mira a Kael. «Ahora lleva la máscara gris. Lleva mensajes para la Corona Hueca. A la novena campanada estará en el Campanario recogiendo un cargamento.»\n\nKael aprieta los puños. «Allí estaré.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_rat"}]};

SC.a2_tower = {bg:"tower", loc:LOC.tower,
  t:["La Torre della Lanterna si avvita nel cielo nero. In cima, dentro una gabbia di ferro, arde una fiamma viola grande come un uomo: la fiamma madre. Tutto intorno, sussurri. Migliaia di voci sottili, ricordi rubati che piangono.\n\nLa sorvegliano accoliti in vesti grigie e una figura alta in armatura, il volto nascosto da un elmo a forma di lanterna.",
     "The Lantern Tower spirals into the black sky. At the top, inside an iron cage, burns a violet flame the size of a man: the mother flame. All around, whispers. Thousands of thin voices, stolen memories weeping.\n\nIt is guarded by acolytes in grey robes and a tall armoured figure, its face hidden by a lantern-shaped helm.",
     "La Torre de la Linterna se retuerce hacia el cielo negro. En lo alto, dentro de una jaula de hierro, arde una llama violeta del tamaño de un hombre: la llama madre. Alrededor, susurros. Miles de voces finas, recuerdos robados que lloran.\n\nLa vigilan acólitos con túnicas grises y una figura alta con armadura, el rostro oculto tras un yelmo con forma de linterna."],
  ch:[{t:["Attaccare","Attack","Atacar"], fight:"tower", win:"a2_tower_won"},{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_tower_won = {bg:"tower", loc:LOC.tower,
  t:["Il Guardiano della Lanterna crolla con un clangore. La fiamma madre si contorce nella gabbia come se ti riconoscesse, e il tuo marchio pulsa al suo stesso ritmo.\n\nPotresti assorbirla: senti che ti renderebbe più forte. Oppure potresti spezzarla e restituire i ricordi alla città.",
     "The Lantern Warden crashes down. The mother flame writhes in its cage as if it recognised you, and your mark pulses in time with it.\n\nYou could absorb it: you feel it would make you stronger. Or you could shatter it and return the memories to the city.",
     "El Guardián de la Linterna se desploma con estrépito. La llama madre se retuerce en su jaula como si te reconociera, y tu marca late a su mismo ritmo.\n\nPodrías absorberla: sientes que te haría más fuerte. O podrías romperla y devolver los recuerdos a la ciudad."],
  ch:[
    {t:["Spezzare la fiamma e liberare i ricordi","Shatter the flame and free the memories","Romper la llama y liberar los recuerdos"], fx(){ set("lamps_freed"); set("tower_done"); xp(200); }, go:"a2_tower_break"},
    {t:["Assorbire la fiamma nel marchio","Absorb the flame into the mark","Absorber la llama en la marca"], fx(){ set("took_flame"); set("tower_done"); S.dark=(S.dark||0)+1; }, go:"a2_tower_take"}]};
SC.a2_tower_break = {bg:"tower", loc:LOC.tower,
  t:["Colpisci la gabbia. La fiamma esplode in mille scintille che volano sopra la città come lucciole. Ovunque, nelle case, la gente si sveglia. Qualcuno ride. Qualcuno piange. Qualcuno chiama un nome che aveva dimenticato.","You strike the cage. The flame bursts into a thousand sparks that fly over the city like fireflies. Everywhere, in the houses, people wake. Someone laughs. Someone weeps. Someone calls out a name they had forgotten.","Golpeas la jaula. La llama estalla en mil chispas que vuelan sobre la ciudad como luciérnagas. Por todas partes, en las casas, la gente despierta. Alguien ríe. Alguien llora. Alguien pronuncia un nombre que había olvidado."],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_tower_take = {bg:"tower", loc:LOC.tower,
  t:()=>cat(["Stendi la mano marchiata. La fiamma viola ti entra nelle vene come vino gelato. Senti la fame di mille ricordi rubati, e la forza che portano con sé: da ora i tuoi colpi infliggono 1d4 danni necrotici in più.\n\nLe lanterne di Vesperia si spengono, ma i ricordi non tornano. Ora sono dentro di te.","You stretch out your marked hand. The violet flame enters your veins like iced wine. You feel the hunger of a thousand stolen memories, and the strength they carry: from now on your hits deal an extra 1d4 necrotic damage.\n\nVesperia's lanterns go dark, but the memories do not return. They are inside you now.","Extiendes la mano marcada. La llama violeta te entra en las venas como vino helado. Sientes el hambre de mil recuerdos robados, y la fuerza que traen consigo: desde ahora tus golpes infligen 1d4 de daño necrótico extra.\n\nLas linternas de Vesperia se apagan, pero los recuerdos no vuelven. Ahora están dentro de ti."],
    ["Brenna distoglie lo sguardo e non dice niente.","Brenna looks away and says nothing.","Brenna aparta la mirada y no dice nada."]),
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};

SC.a2_bell = {bg:"bell", loc:LOC.bell,
  t:["La Torre Campanaria. Il nono rintocco fa tremare le pietre. Sul ballatoio, un uomo con la maschera grigia aspetta accanto a una cassa, insieme ad alcuni cultisti. Quando si volta, Kael si irrigidisce: hanno gli stessi occhi.\n\n«Kael.» La voce di Doran è stanca. «Dovevi restare lontano.»",
     "The Bell Tower. The ninth stroke makes the stones tremble. On the gallery, a man in a grey mask waits beside a crate with a few cultists. When he turns, Kael stiffens: they have the same eyes.\n\n“Kael.” Doran's voice is weary. “You should have stayed away.”",
     "El Campanario. La novena campanada hace temblar las piedras. En la galería, un hombre con máscara gris espera junto a una caja con algunos sectarios. Cuando se vuelve, Kael se pone rígido: tienen los mismos ojos.\n\n«Kael.» La voz de Doran suena cansada. «Debías mantenerte lejos.»"],
  ch:[
    {t:["Lasciare che sia Kael a parlargli","Let Kael speak to him","Dejar que Kael le hable"], check:{sk:"pers", dc:14, ok:"a2_doran_ok", ko:"a2_doran_fight", adv:()=>true}},
    {t:["«Dicci dove tengono i marchiati.»","“Tell us where they keep the marked.”","«Dinos dónde tienen a los marcados.»"], check:{sk:"inti", dc:15, ok:"a2_doran_info", ko:"a2_doran_fight"}},
    {t:["Attaccare","Attack","Atacar"], fight:"doran", win:"a2_doran_dead"}]};
SC.a2_doran_ok = {bg:"bell", loc:LOC.bell, once(){ set("doran_ally"); set("doran_done"); xp(400); },
  t:["Kael posa le armi e si avvicina al fratello. Parla piano: della madre, del forno dove rubavano il pane da bambini, della promessa che si erano fatti sul ponte vecchio. Alla fine Doran si toglie la maschera. Piange.\n\n«Mi avevano detto che il nuovo dio avrebbe sfamato tutti. Ho visto cosa mangia, Kael.» I cultisti fuggono giù per le scale. Doran si volta verso di te. «La fortezza della Corona di Cenere ha un passaggio segreto, nelle vecchie cisterne. Vi ci porterò io, quando sarà il momento.»",
     "Kael lays down his weapons and approaches his brother. He speaks softly: of their mother, of the bakery they robbed as children, of the promise they made on the old bridge. In the end Doran takes off his mask. He is weeping.\n\n“They told me the new god would feed everyone. I've seen what it eats, Kael.” The cultists flee down the stairs. Doran turns to you. “The Crown of Ash fortress has a secret way in, through the old cisterns. I'll take you there myself, when the time comes.”",
     "Kael deja las armas y se acerca a su hermano. Habla bajo: de su madre, de la panadería a la que robaban de niños, de la promesa que se hicieron en el puente viejo. Al final Doran se quita la máscara. Llora.\n\n«Me dijeron que el nuevo dios daría de comer a todos. He visto lo que come, Kael.» Los sectarios huyen escaleras abajo. Doran se vuelve hacia ti. «La fortaleza de la Corona de Ceniza tiene un paso secreto, por las viejas cisternas. Yo mismo os llevaré allí, cuando llegue el momento.»"],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_doran_info = {bg:"bell", loc:LOC.bell, once(){ set("doran_info"); set("doran_done"); xp(250); },
  t:["Doran arretra, la mano sull'elsa. «Va bene! Alla Corona di Cenere, sul picco. I sei marchiati sono nelle prigioni sotto la sala del trono. Il rito si compirà all'Ultimo Buio.»\n\nPoi salta dal ballatoio su un tetto e sparisce nella notte. Kael resta a guardare il vuoto.","Doran backs away, hand on his hilt. “All right! At the Crown of Ash, on the peak. The six marked are in the cells under the throne room. The rite will be completed at the Last Dark.”\n\nThen he leaps from the gallery onto a roof and vanishes into the night. Kael is left staring into the void.","Doran retrocede, con la mano en la empuñadura. «¡Está bien! En la Corona de Ceniza, en el pico. Los seis marcados están en las celdas bajo el salón del trono. El rito se completará en la Última Oscuridad.»\n\nLuego salta de la galería a un tejado y desaparece en la noche. Kael se queda mirando al vacío."],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_doran_fight = {bg:"bell", loc:LOC.bell,
  t:["«Mi dispiace, fratellino.» Doran sguaina due lame.","“I'm sorry, little brother.” Doran draws two blades.","«Lo siento, hermanito.» Doran desenvaina dos hojas."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"doran", win:"a2_doran_dead"}]};
SC.a2_doran_dead = {bg:"bell", loc:LOC.bell, once(){ set("doran_dead"); set("doran_done"); },
  t:["Doran giace sulle pietre della torre. Kael gli toglie la maschera e gli chiude gli occhi. Non dice niente per molto tempo.\n\nPoi trova nella cassa una mappa della Corona di Cenere, con le vecchie cisterne segnate in rosso, e se la mette in tasca. «Andiamo.»","Doran lies on the tower stones. Kael removes his mask and closes his eyes. He says nothing for a long time.\n\nThen he finds in the crate a map of the Crown of Ash, the old cisterns marked in red, and pockets it. “Let's go.”","Doran yace sobre las piedras de la torre. Kael le quita la máscara y le cierra los ojos. No dice nada durante mucho tiempo.\n\nLuego encuentra en la caja un mapa de la Corona de Ceniza, con las viejas cisternas marcadas en rojo, y se lo guarda. «Vámonos.»"],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};

SC.a2_masq = {bg:"palace", loc:LOC.palace,
  t:["Il palazzo ducale scintilla di lanterne viola. Nobili mascherati ballano con movimenti meccanici, sorrisi fissi. Al centro il Duca Malvern, un uomo grasso con una maschera a forma di sole dorato, ride troppo forte. Le sue guardie del corpo non proiettano ombra.\n\nLa porta del suo studio privato è in fondo a un corridoio sorvegliato.",
     "The ducal palace glitters with violet lanterns. Masked nobles dance with mechanical movements and fixed smiles. At the centre, Duke Malvern, a fat man in a golden sun mask, laughs too loudly. His bodyguards cast no shadow.\n\nThe door to his private study lies at the end of a guarded corridor.",
     "El palacio ducal centellea de linternas violetas. Nobles enmascarados bailan con movimientos mecánicos y sonrisas fijas. En el centro, el Duque Malvern, un hombre gordo con una máscara de sol dorado, ríe demasiado fuerte. Sus guardaespaldas no proyectan sombra.\n\nLa puerta de su estudio privado está al fondo de un pasillo vigilado."],
  ch:[
    {t:["Sgattaiolare nello studio","Slip into the study","Colarse en el estudio"], check:{sk:"ste", dc:14, ok:"a2_masq_ledger", ko:"a2_masq_caught"}},
    {t:["Distrarre le guardie con una conversazione brillante","Distract the guards with sparkling conversation","Distraer a los guardias con una conversación brillante"], check:{sk:"dec", dc:13, ok:"a2_masq_ledger", ko:"a2_masq_caught"}},
    {t:["Affrontare il Duca a viso aperto","Confront the Duke openly","Enfrentarse al Duque abiertamente"], go:"a2_masq_confront"}]};
SC.a2_masq_ledger = {bg:"palace", loc:LOC.palace, once(){ set("ledger"); xp(150); },
  t:["Lo studio puzza di cera e vino. Nel cassetto della scrivania c'è un registro rilegato in pelle grigia: ogni pagina un patto.\n\n«Mille lanterne in cambio della fedeltà della città. Cento marchiati e bambini consegnati in cambio del titolo di Re di Vesperia, quando il nuovo dio sorgerà.» Firmato Malvern, controfirmato con una corona vuota.","The study stinks of wax and wine. In the desk drawer lies a ledger bound in grey leather: every page a pact.\n\n“A thousand lanterns in exchange for the city's loyalty. A hundred marked and children delivered in exchange for the title of King of Vesperia, when the new god rises.” Signed Malvern, countersigned with an empty crown.","El estudio apesta a cera y vino. En el cajón del escritorio hay un registro encuadernado en piel gris: cada página un pacto.\n\n«Mil linternas a cambio de la lealtad de la ciudad. Cien marcados y niños entregados a cambio del título de Rey de Vesperia, cuando el nuevo dios se alce.» Firmado Malvern, refrendado con una corona vacía."],
  ch:[{t:["Tornare nella sala da ballo","Return to the ballroom","Volver al salón de baile"], go:"a2_masq_confront"}]};
SC.a2_masq_caught = {bg:"palace", loc:LOC.palace,
  t:["«Ehi, voi!» Una guardia senz'ombra vi sbarra la strada. Il Duca si volta, incuriosito. «Ospiti che si perdono. Portateli da me.»","“Hey, you!” A shadowless guard blocks your way. The Duke turns, intrigued. “Guests who get lost. Bring them to me.”","«¡Eh, vosotros!» Un guardia sin sombra os corta el paso. El Duque se vuelve, intrigado. «Invitados que se pierden. Traédmelos.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_masq_confront"}]};
SC.a2_masq_confront = {bg:"palace", loc:LOC.palace,
  t:["Il Duca Malvern vi squadra da dietro la maschera dorata. Vede il marchio e si lecca le labbra. «Il settimo! Che onore. La Madre sarà contenta.»","Duke Malvern sizes you up from behind his golden mask. He sees the mark and licks his lips. “The seventh! What an honour. Mother will be pleased.”","El Duque Malvern os examina tras su máscara dorada. Ve la marca y se relame. «¡El séptimo! Qué honor. La Madre estará contenta.»"],
  ch:[
    {t:["Leggere il registro ad alta voce davanti a tutti","Read the ledger aloud for all to hear","Leer el registro en voz alta delante de todos"], req:()=>has("ledger"), check:{sk:"pers", dc:12, ok:"a2_masq_expose", ko:"a2_masq_fight"}},
    {t:["«Cento marchiati, Malvern? Quanto vale il mio silenzio?»","“A hundred marked, Malvern? What's my silence worth?”","«¿Cien marcados, Malvern? ¿Cuánto vale mi silencio?»"], req:()=>has("ledger"), go:"a2_masq_deal"},
    {t:["Attaccare il Duca","Attack the Duke","Atacar al Duque"], go:"a2_masq_fight"},
    {t:["Ritirarsi educatamente","Withdraw politely","Retirarse educadamente"], go:"vesperia"}]};
SC.a2_masq_expose = {bg:"palace", loc:LOC.palace,
  t:["Leggi. La musica si ferma. Un nobile si toglie la maschera, poi un altro. «Mia figlia era marchiata» dice una donna. «Mi avevi detto che era partita per il sud.»\n\nLa sala ruggisce. Il Duca indietreggia e chiama le sue guardie senz'ombra.","You read. The music stops. A noble removes his mask, then another. “My daughter was marked,” says a woman. “You told me she'd gone south.”\n\nThe hall roars. The Duke backs away, calling for his shadowless guards.","Lees. La música se detiene. Un noble se quita la máscara, luego otro. «Mi hija estaba marcada» dice una mujer. «Me dijiste que se había ido al sur.»\n\nEl salón ruge. El Duque retrocede y llama a sus guardias sin sombra."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"duke", win:"a2_masq_won"}]};
SC.a2_masq_won = {bg:"palace", loc:LOC.palace, once(){ set("guard_ally"); set("masq_done"); xp(300); gold(80); },
  t:["Le guardie senz'ombra si dissolvono in fumo. Il Duca è in ginocchio, la maschera spaccata, circondato dai nobili.\n\nIl capitano della guardia cittadina si toglie l'elmo. «La guardia di Vesperia è con voi, marchiato. Dite solo dove.»","The shadowless guards dissolve into smoke. The Duke kneels, mask cracked, surrounded by the nobles.\n\nThe captain of the city watch removes his helm. “The guard of Vesperia stands with you, marked one. Just say where.”","Los guardias sin sombra se disuelven en humo. El Duque está de rodillas, la máscara rota, rodeado por los nobles.\n\nEl capitán de la guardia de la ciudad se quita el yelmo. «La guardia de Vesperia está con vosotros, marcado. Solo decid dónde.»"],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_masq_deal = {bg:"palace", loc:LOC.palace, once(){ set("duke_deal"); set("masq_done"); gold(200); },
  t:["Il Duca ride, nervoso, e ti mette in mano una borsa pesante. «Duecento monete d'oro. E la mia parola che non ci siamo mai visti.»\n\nMentre uscite, senti il suo sguardo sulla nuca.","The Duke laughs nervously and presses a heavy purse into your hand. “Two hundred gold coins. And my word that we never met.”\n\nAs you leave, you feel his eyes on the back of your neck.","El Duque ríe, nervioso, y te pone en la mano una bolsa pesada. «Doscientas monedas de oro. Y mi palabra de que nunca nos hemos visto.»\n\nMientras salís, sientes su mirada en la nuca."],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_masq_fight = {bg:"palace", loc:LOC.palace,
  t:["Il Duca strilla: «Prendeteli! Il marchiato lo voglio vivo!»","The Duke shrieks: “Seize them! I want the marked one alive!”","El Duque chilla: «¡Prendedlos! ¡Al marcado lo quiero vivo!»"],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"duke", win:"a2_masq_won2"}]};
SC.a2_masq_won2 = {bg:"palace", loc:LOC.palace, once(){ set("masq_done"); xp(200); },
  t:["Le guardie senz'ombra si dissolvono. Il Duca fugge da un passaggio segreto, ma la sala ha visto tutto. Nessuno vi ferma mentre uscite.","The shadowless guards dissolve. The Duke flees through a secret passage, but the hall has seen everything. No one stops you as you leave.","Los guardias sin sombra se disuelven. El Duque huye por un pasadizo secreto, pero el salón lo ha visto todo. Nadie os detiene al salir."],
  ch:[{t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};

SC.a2_sewers = {bg:"sewer", loc:LOC.sewer,
  t:["Le fogne della Città Bassa puzzano di morte e di carta bagnata. L'acqua nera arriva alle ginocchia. Più avanti qualcosa sguazza.","The Lower City sewers reek of death and wet paper. The black water comes up to your knees. Ahead, something splashes.","Las cloacas de la Ciudad Baja apestan a muerte y a papel mojado. El agua negra os llega a las rodillas. Más adelante algo chapotea."],
  ch:[
    {t:["Avanzare con attenzione","Advance carefully","Avanzar con cuidado"], check:{sk:"per", dc:13, ok:"a2_sew_cache", ko:"a2_sew_fight"}},
    {t:["Proseguire senza indugio","Push straight on","Seguir sin vacilar"], go:"a2_sew_fight"},
    {t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.a2_sew_cache = {bg:"sewer", loc:LOC.sewer, once(){ item("potion",2); gold(30); },
  t:["Tra i detriti noti una sacca di cuoio incastrata in una grata: un contrabbandiere sfortunato. Dentro, due pozioni e qualche moneta. E noti i ratti giganti prima che loro notino voi.","Among the debris you spot a leather satchel caught in a grate: an unlucky smuggler. Inside, two potions and some coins. And you spot the giant rats before they spot you.","Entre los escombros ves una bolsa de cuero atascada en una rejilla: un contrabandista sin suerte. Dentro, dos pociones y algunas monedas. Y ves a las ratas gigantes antes de que ellas os vean."],
  ch:[{t:["Attaccare per primi","Strike first","Atacar primero"], fight:"sewer", surprise:1, win:"a2_drowned1"}]};
SC.a2_sew_fight = {bg:"sewer", loc:LOC.sewer,
  t:["Ratti grossi come cani emergono dall'acqua, seguiti da un corpo gonfio che cammina.","Rats as big as dogs surge from the water, followed by a bloated body that walks.","Ratas grandes como perros emergen del agua, seguidas de un cuerpo hinchado que camina."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"sewer", win:"a2_drowned1"}]};

SC.a2_drowned1 = {bg:"drowned", loc:LOC.drowned,
  t:["L'Archivio Sommerso. Sale intere invase dall'acqua, libri che galleggiano come pesci morti, scaffali crollati. La luce verdastra viene da un muschio fosforescente.\n\nE ci sono gli annegati: archivisti e guardie, in piedi nell'acqua con gli occhi bianchi, che si voltano lentamente verso di voi.","The Drowned Archive. Whole halls flooded, books floating like dead fish, shelves collapsed. The greenish light comes from phosphorescent moss.\n\nAnd there are the drowned: archivists and guards, standing in the water with white eyes, slowly turning toward you.","El Archivo Sumergido. Salas enteras inundadas, libros flotando como peces muertos, estanterías derrumbadas. La luz verdosa viene de un musgo fosforescente.\n\nY están los ahogados: archiveros y guardias, de pie en el agua con los ojos blancos, que se vuelven lentamente hacia vosotros."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"drowned", win:"a2_drowned2"}]};
SC.a2_drowned2 = {bg:"drowned", loc:LOC.drowned,
  t:["Una porta di bronzo blocca il corridoio, ornata da un sole a sette raggi. Due armature vuote la fiancheggiano. Quando ti avvicini, gli elmi si voltano verso di te e una voce rimbomba:\n\n«Chi custodì la prima alba, e con cosa la chiuse?»","A bronze door blocks the corridor, decorated with a seven-rayed sun. Two empty suits of armour flank it. As you approach, the helms turn toward you and a voice booms:\n\n“Who kept the first dawn, and with what did they lock it?”","Una puerta de bronce bloquea el pasillo, adornada con un sol de siete rayos. Dos armaduras vacías la flanquean. Al acercarte, los yelmos se vuelven hacia ti y una voz retumba:\n\n«¿Quién custodió el primer alba, y con qué la cerró?»"],
  ch:[
    {t:["«I Custodi del Sole, con una chiave d'oro.»","“The Sunwardens, with a golden key.”","«Los Custodios del Sol, con una llave de oro.»"], req:()=>has("lore1") || has("song") || has("lore2"), go:"a2_door_ok"},
    {t:["Ricordare le antiche storie","Recall the old stories","Recordar las viejas historias"], req:()=>!(has("lore1") || has("song") || has("lore2")), check:{sk:"his", dc:13, ok:"a2_door_ok", ko:"a2_door_fight"}},
    {t:["«Morrhan, con la fame.»","“Morrhan, with hunger.”","«Morrhan, con el hambre.»"], go:"a2_door_fight"},
    {t:["Attaccare le armature","Attack the armours","Atacar las armaduras"], go:"a2_door_fight"}]};
SC.a2_door_ok = {bg:"drowned", loc:LOC.drowned, once(){ xp(400); },
  t:["«Passa, figlio della notte.» Le armature si inginocchiano, e la porta si apre con un sospiro d'aria secca.","“Pass, child of night.” The armours kneel, and the door opens with a sigh of dry air.","«Pasa, hijo de la noche.» Las armaduras se arrodillan, y la puerta se abre con un suspiro de aire seco."],
  ch:[{t:["Entrare","Enter","Entrar"], go:"a2_ilyra"}]};
SC.a2_door_fight = {bg:"drowned", loc:LOC.drowned,
  t:["«Menzogna.» Le armature sollevano i pugni d'acciaio.","“Falsehood.” The armours raise their steel fists.","«Mentira.» Las armaduras alzan sus puños de acero."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"guardians", win:"a2_ilyra"}]};

SC.a2_ilyra = {bg:"drowned", loc:LOC.drowned,
  t:["Oltre la porta c'è una cella asciutta, protetta da una bolla di luce azzurra che tiene lontana l'acqua. Dentro, un'elfa dai capelli grigio cenere legge un libro, seduta su una pila di altri libri. Alza gli occhi senza fretta.\n\n«Finalmente. Sono tre settimane che aspetto qualcuno che non sia un cadavere. Ilyra delle Foglie Grigie.» Guarda il tuo marchio. «Oh. Questo spiega molte cose.»","Beyond the door is a dry cell, protected by a bubble of blue light that keeps the water out. Inside, an elf with ash-grey hair reads a book, sitting on a stack of other books. She looks up unhurriedly.\n\n“Finally. I've spent three weeks waiting for someone who isn't a corpse. Ilyra of the Grey Leaves.” She looks at your mark. “Oh. That explains a great deal.”","Tras la puerta hay una celda seca, protegida por una burbuja de luz azul que mantiene el agua fuera. Dentro, una elfa de cabello gris ceniza lee un libro, sentada sobre una pila de otros libros. Levanta la vista sin prisa.\n\n«Por fin. Llevo tres semanas esperando a alguien que no sea un cadáver. Ilyra de las Hojas Grises.» Mira tu marca. «Oh. Eso explica muchas cosas.»"],
  ch:[{t:["Spezzare il sigillo della cella","Break the cell's seal","Romper el sello de la celda"], check:{sk:"arc", dc:12, ok:"a2_ilyra_free", ko:"a2_ilyra_shock"}}]};
SC.a2_ilyra_shock = {bg:"drowned", loc:LOC.drowned, once(){ dmgParty(4); },
  t:["Il sigillo ti dà una scossa che ti fa vibrare i denti. Ilyra sospira e lo dissolve dall'interno con un gesto. «Il trucco è non toccarlo.»","The seal gives you a jolt that rattles your teeth. Ilyra sighs and dissolves it from the inside with a gesture. “The trick is not to touch it.”","El sello te da una descarga que te hace castañetear los dientes. Ilyra suspira y lo disuelve desde dentro con un gesto. «El truco es no tocarlo.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_ilyra_free"}]};
SC.a2_ilyra_free = {bg:"drowned", loc:LOC.drowned, once(){ join("ilyra"); xp(100); },
  t:["Ilyra si stiracchia. «Il Duca mi ha rinchiusa perché ho scoperto che il sole non è morto: è stato rubato. Qualcuno ne ha legato la luce a sette persone. Sette marchi. Il tuo è il più forte.»\n\nInfila i libri in uno zaino impossibilmente piccolo. «Vengo con voi. Non per gentilezza: voglio vedere come va a finire.»","Ilyra stretches. “The Duke locked me up because I discovered the sun isn't dead: it was stolen. Someone bound its light to seven people. Seven marks. Yours is the strongest.”\n\nShe stuffs the books into an impossibly small pack. “I'm coming with you. Not out of kindness: I want to see how it ends.”","Ilyra se estira. «El Duque me encerró porque descubrí que el sol no ha muerto: lo robaron. Alguien ató su luz a siete personas. Siete marcas. La tuya es la más fuerte.»\n\nMete los libros en una mochila imposiblemente pequeña. «Voy con vosotros. No por amabilidad: quiero ver cómo acaba.»"],
  ch:[{t:["Scendere verso la cripta","Descend toward the crypt","Bajar hacia la cripta"], go:"a2_vault"}]};

SC.a2_vault = {bg:"drowned", loc:LOC.drowned,
  t:["Più in basso, oltre una scala a chiocciola sommersa, si apre la cripta della Chiave. Su un piedistallo, sopra il pelo dell'acqua, brilla un oggetto dorato: una chiave lunga come un avambraccio, a forma di raggio di sole.\n\nMa tra voi e la chiave l'acqua si solleva e prende forma: un'ombra con una corona di alghe nere. Il Custode Annegato.","Further down, past a flooded spiral stair, opens the crypt of the Key. On a pedestal above the waterline gleams a golden object: a key as long as a forearm, shaped like a sunbeam.\n\nBut between you and the key the water rises and takes shape: a shadow crowned with black weed. The Drowned Keeper.","Más abajo, tras una escalera de caracol sumergida, se abre la cripta de la Llave. Sobre un pedestal, por encima del agua, brilla un objeto dorado: una llave larga como un antebrazo, con forma de rayo de sol.\n\nPero entre vosotros y la llave el agua se alza y toma forma: una sombra con una corona de algas negras. El Guardián Ahogado."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"keeper", win:"a2_key"}]};
SC.a2_key = {bg:"drowned", loc:LOC.drowned, once(){ set("has_key"); item("key",1); xp(200); },
  t:["Quando stringi la Chiave dell'Alba, il marchio sulla tua mano si accende di luce bianca. Una visione: un picco di cenere, una fortezza nera, un altare. Sei persone in catene. E una donna velata di nero, di spalle, che si volta lentamente…\n\nLa visione si spezza. Ilyra legge l'iscrizione sul piedistallo: «Solo il marchio del buio gira la chiave dell'alba.» Ti guarda. «Te ne rendi conto? Questa chiave poteva prenderla solo un marchiato. Chiunque abbia allagato l'Archivio non poteva toccarla. Aveva bisogno di te.»","As you grasp the Key of Dawn, the mark on your hand blazes with white light. A vision: a peak of ash, a black fortress, an altar. Six people in chains. And a woman veiled in black, her back to you, slowly turning…\n\nThe vision breaks. Ilyra reads the inscription on the pedestal: “Only the mark of darkness turns the key of dawn.” She looks at you. “Do you see? Only a marked one could take this key. Whoever flooded the Archive couldn't touch it. They needed you.”","Al empuñar la Llave del Alba, la marca de tu mano se enciende con luz blanca. Una visión: un pico de ceniza, una fortaleza negra, un altar. Seis personas encadenadas. Y una mujer velada de negro, de espaldas, que se vuelve lentamente…\n\nLa visión se rompe. Ilyra lee la inscripción del pedestal: «Solo la marca de la oscuridad gira la llave del alba.» Te mira. «¿Te das cuenta? Solo un marcado podía coger esta llave. Quien inundó el Archivo no podía tocarla. Te necesitaba a ti.»"],
  ch:[{t:["Tornare a Vesperia","Return to Vesperia","Volver a Vesperia"], go:"vesperia"}]};

SC.a2_betrayal = {bg:"archive", loc:LOC.archive,
  t:["Tornate all'Archivio. Pellin vi aspetta tra gli scaffali, ma non è solo. Accanto a lui, avvolta in un mantello da viaggio, c'è Madre Seraphine. Sorride, dolce e stanca come sempre.\n\n«Figlio mio. Sono venuta appena ho saputo. Vesperia non è sicura: dammi la Chiave, la porterò al tempio di Ashford, dove nessuno la cercherà.»\n\nPellin ha le mani che tremano.","You return to the Archive. Pellin is waiting among the shelves, but he is not alone. Beside him, wrapped in a travelling cloak, stands Mother Seraphine. She smiles, gentle and tired as ever.\n\n“My child. I came as soon as I heard. Vesperia isn't safe: give me the Key, I'll take it to the shrine at Ashford, where no one will look for it.”\n\nPellin's hands are shaking.","Volvéis al Archivo. Pellin os espera entre las estanterías, pero no está solo. A su lado, envuelta en una capa de viaje, está la Madre Seraphine. Sonríe, dulce y cansada como siempre.\n\n«Hijo mío. Vine en cuanto lo supe. Vesperia no es segura: dame la Llave, la llevaré al templo de Ashford, donde nadie la buscará.»\n\nA Pellin le tiemblan las manos."],
  ch:[
    {t:["Consegnarle la Chiave","Hand her the Key","Entregarle la Llave"], go:"a2_rev_give"},
    {t:["«No. La Chiave resta con me.»","“No. The Key stays with me.”","«No. La Llave se queda conmigo.»"], go:"a2_rev_refuse"},
    {t:["«Mortimer è morto l'inverno scorso. M sta per Madre, vero?»","“Mortimer died last winter. M stands for Mother, doesn't it?”","«Mortimer murió el invierno pasado. La M es de Madre, ¿verdad?»"], req:()=>has("sus_ser") || has("sus_ser2") || has("sus_mort"), go:"a2_rev_know"}]};
SC.a2_rev_give = {bg:"archive", loc:LOC.archive, once(){ take("key"); set("gave_key"); },
  t:["Seraphine prende la Chiave tra le mani come una reliquia. «Grazie» sussurra. «Sei stato perfetto.»\n\nPoi il suo volto cambia: la pelle si fa grigia come cenere, gli occhi diventano due piccoli soli neri. Pellin cerca di fuggire; un'ombra lo attraversa e lui cade senza un grido.\n\n«Ti ho liberato io da quel carro» dice la Madre della Notte. «Ti ho mandato a salvare i bambini perché ti fidassi. Ti ho mandato qui perché solo tu potevi toccare la Chiave. Ora vieni alla Corona di Cenere, figlio mio. Il dio ha fame, e tu sei il banchetto.»\n\nSvanisce in un vortice di fumo nero.","Seraphine takes the Key in her hands like a relic. “Thank you,” she whispers. “You were perfect.”\n\nThen her face changes: her skin turns ash-grey, her eyes become two small black suns. Pellin tries to flee; a shadow passes through him and he falls without a cry.\n\n“I freed you from that cart,” says the Mother of Night. “I sent you to save the children so you would trust me. I sent you here because only you could touch the Key. Now come to the Crown of Ash, my child. The god is hungry, and you are the feast.”\n\nShe vanishes in a whirl of black smoke.","Seraphine toma la Llave entre sus manos como una reliquia. «Gracias» susurra. «Has sido perfecto.»\n\nLuego su rostro cambia: la piel se vuelve gris como la ceniza, los ojos se convierten en dos pequeños soles negros. Pellin intenta huir; una sombra lo atraviesa y cae sin un grito.\n\n«Yo te liberé de ese carro» dice la Madre de la Noche. «Te envié a salvar a los niños para que confiaras en mí. Te envié aquí porque solo tú podías tocar la Llave. Ahora ven a la Corona de Ceniza, hijo mío. El dios tiene hambre, y tú eres el banquete.»\n\nDesaparece en un torbellino de humo negro."],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_after"}]};
SC.a2_rev_refuse = {bg:"archive", loc:LOC.archive,
  t:["Il sorriso di Seraphine non cambia. Ma i suoi occhi sì: diventano due piccoli soli neri. «Peccato. Speravo saresti stato gentile fino alla fine.»\n\nPellin cerca di fuggire; un'ombra lo attraversa e lui cade senza un grido. Dalle ombre degli scaffali escono servitori in grigio, armati.","Seraphine's smile does not change. But her eyes do: they become two small black suns. “Pity. I hoped you'd be kind to the end.”\n\nPellin tries to flee; a shadow passes through him and he falls without a cry. From the shadows of the shelves step servants in grey, armed.","La sonrisa de Seraphine no cambia. Pero sus ojos sí: se convierten en dos pequeños soles negros. «Lástima. Esperaba que fueras amable hasta el final.»\n\nPellin intenta huir; una sombra lo atraviesa y cae sin un grito. De las sombras de las estanterías salen sirvientes de gris, armados."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"ser_guards", win:"a2_rev_after"}]};
SC.a2_rev_know = {bg:"archive", loc:LOC.archive, once(){ set("unmasked"); xp(150); },
  t:["Seraphine ride piano: una risata vera, quasi affettuosa. «Bravo. Ti avevo sottovalutato.» La sua pelle si fa grigia come cenere. «Sì. M sta per Madre. Madre della Notte.»\n\nPellin cerca di fuggire; un'ombra lo attraversa e lui cade senza un grido. «Ma sapere non ti salverà.» Dalle ombre escono i suoi servi.","Seraphine laughs softly: a real laugh, almost fond. “Well done. I underestimated you.” Her skin turns ash-grey. “Yes. M stands for Mother. Mother of Night.”\n\nPellin tries to flee; a shadow passes through him and he falls without a cry. “But knowing won't save you.” Her servants emerge from the shadows.","Seraphine se ríe bajito: una risa auténtica, casi afectuosa. «Bravo. Te había subestimado.» Su piel se vuelve gris como la ceniza. «Sí. La M es de Madre. Madre de la Noche.»\n\nPellin intenta huir; una sombra lo atraviesa y cae sin un grito. «Pero saberlo no te salvará.» De las sombras salen sus siervos."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"ser_guards", win:"a2_rev_after"}]};
SC.a2_rev_after = {bg:"archive", loc:LOC.archive, once(){ take("key"); },
  t:["L'ultimo servitore cade. Ma Seraphine non ha combattuto: aspettava. Il tuo marchio esplode di dolore, come se una mano ti stringesse il cuore, e la Chiave ti scivola dalle dita. Lei la raccoglie.\n\n«Il marchio ti lega a me, figlio mio. Non puoi rifiutarmi davvero.» Poi, piano: «Vieni alla Corona di Cenere. Il dio ha fame.»\n\nE svanisce in un vortice di fumo nero.","The last servant falls. But Seraphine hasn't fought: she was waiting. Your mark explodes with pain, as if a hand were crushing your heart, and the Key slips from your fingers. She picks it up.\n\n“The mark binds you to me, my child. You cannot truly refuse me.” Then, softly: “Come to the Crown of Ash. The god is hungry.”\n\nAnd she vanishes in a whirl of black smoke.","Cae el último sirviente. Pero Seraphine no ha luchado: esperaba. Tu marca estalla de dolor, como si una mano te apretara el corazón, y la Llave se te escapa de los dedos. Ella la recoge.\n\n«La marca te ata a mí, hijo mío. No puedes rechazarme de verdad.» Luego, en voz baja: «Ven a la Corona de Ceniza. El dios tiene hambre.»\n\nY desaparece en un torbellino de humo negro."],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_after"}]};
SC.a2_after = {bg:"archive", loc:LOC.archive, once(){ set("act2_done"); xp(300); toastQ(["Nuova missione: La Corona di Cenere","New quest: The Crown of Ash","Nueva misión: La Corona de Ceniza"]); },
  t:["Silenzio. Pellin è morto tra i suoi libri. Brenna gli chiude gli occhi.\n\nIlyra è la prima a parlare, con la voce rotta. «Ragioniamo. Ha la Chiave, ma la Chiave funziona solo nelle mani di un marchiato vivo. Per questo vuole te. All'Ultimo Buio aprirà la porta di Morrhan usando il tuo marchio, e consumerà gli altri sei come combustibile.»\n\n«Allora non andiamo» dice qualcuno. Ilyra scuote la testa. «Se non andiamo, il rito prenderà comunque i sei, e il buio diventerà eterno. Se andiamo, possiamo sperare di usare la Chiave prima di lei.»\n\nBrenna solleva il martello. «Allora andiamo. Tutti.»","Silence. Pellin lies dead among his books. Brenna closes his eyes.\n\nIlyra is the first to speak, her voice cracked. “Let's think. She has the Key, but the Key only works in the hands of a living marked one. That's why she wants you. At the Last Dark she'll open Morrhan's door using your mark, and burn the other six as fuel.”\n\n“Then we don't go,” someone says. Ilyra shakes her head. “If we don't go, the rite will take the six anyway, and the dark becomes eternal. If we go, we can hope to use the Key before she does.”\n\nBrenna raises her hammer. “Then we go. All of us.”","Silencio. Pellin yace muerto entre sus libros. Brenna le cierra los ojos.\n\nIlyra es la primera en hablar, con la voz rota. «Pensemos. Tiene la Llave, pero la Llave solo funciona en manos de un marcado vivo. Por eso te quiere a ti. En la Última Oscuridad abrirá la puerta de Morrhan usando tu marca, y consumirá a los otros seis como combustible.»\n\n«Entonces no vamos» dice alguien. Ilyra niega con la cabeza. «Si no vamos, el rito se llevará igualmente a los seis, y la oscuridad será eterna. Si vamos, podemos esperar usar la Llave antes que ella.»\n\nBrenna alza el martillo. «Entonces vamos. Todos.»"],
  ch:[
    {t:["«Andiamo alla Corona di Cenere.»","“To the Crown of Ash.”","«A la Corona de Ceniza.»"], go:"a3_title"},
    {t:["Prima voglio prepararmi in città","First I want to prepare in the city","Antes quiero prepararme en la ciudad"], go:"vesperia"}]};

/* -------------------- OPTIONAL DUNGEON: THE VAULTS OF AUREL -------------------- */
const LOC_V = ["Le Volte di Aurel","The Vaults of Aurel","Las Bóvedas de Aurel"];
SC.v_pellin = {bg:"archive", loc:LOC.archive, once(){ set("vault_known"); toastQ(["Nuova missione: Le Volte di Aurel","New quest: The Vaults of Aurel","Nueva misión: Las Bóvedas de Aurel"]); },
  t:["Pellin abbassa la voce. «Le Volte di Aurel. I Custodi del Sole vi deponevano le armi dei loro morti, insieme a ciò che non volevano finisse nelle mani sbagliate. Sono sigillate da trecento anni.»\n\nSi gratta la barba, a disagio. «Da quando il sole si è spento, il sigillo si è incrinato. Di notte si sentono passi, là sotto. Passi pesanti, metallici. Se cercate armi degne di affrontare il buio, sono lì. Ma i Custodi non lasciavano le loro cose incustodite.»",
     "Pellin lowers his voice. “The Vaults of Aurel. The Sunwardens laid their dead's weapons there, along with things they did not want falling into the wrong hands. They've been sealed for three hundred years.”\n\nHe scratches his beard, uneasy. “Since the sun went out, the seal has cracked. At night you can hear footsteps down there. Heavy, metallic footsteps. If you seek weapons fit to face the dark, they're there. But the Sunwardens never left their things unguarded.”",
     "Pellin baja la voz. «Las Bóvedas de Aurel. Los Custodios del Sol depositaban allí las armas de sus muertos, junto con lo que no querían que cayera en malas manos. Llevan trescientos años selladas.»\n\nSe rasca la barba, incómodo. «Desde que se apagó el sol, el sello se ha agrietado. De noche se oyen pasos ahí abajo. Pasos pesados, metálicos. Si buscáis armas dignas de enfrentar la oscuridad, están allí. Pero los Custodios nunca dejaban sus cosas sin vigilancia.»"],
  ch:[{t:["Continuare","Go on","Continuar"], go:"a2_archive"}]};
SC.v_enter = {bg:"crypt", loc:LOC_V,
  t:["Una scala a chiocciola scende nel buio sotto la cappella. L'aria sa di polvere e ferro. In fondo, un lungo corridoio lastricato: alcune lastre sono più lucide delle altre, come se qualcuno le avesse calpestate di recente. O come se fossero fatte per essere calpestate.",
     "A spiral stair descends into the dark beneath the chapel. The air smells of dust and iron. At the bottom, a long flagstone corridor: some flags are shinier than the rest, as if someone had walked on them recently. Or as if they were made to be walked on.",
     "Una escalera de caracol desciende a la oscuridad bajo la capilla. El aire huele a polvo y hierro. Al fondo, un largo pasillo enlosado: algunas losas brillan más que las otras, como si alguien las hubiera pisado hace poco. O como si estuvieran hechas para pisarlas."],
  ch:[
    {t:["Studiare il pavimento prima di avanzare","Study the floor before advancing","Estudiar el suelo antes de avanzar"], check:{sk:"per", dc:13, ok:"v_trap_ok", ko:"v_trap_ko"}},
    {t:["Avanzare in fretta","Hurry on","Avanzar deprisa"], go:"v_trap_ko"},
    {t:["Tornare in città","Return to the city","Volver a la ciudad"], go:"vesperia"}]};
SC.v_trap_ok = {bg:"crypt", loc:LOC_V, once(){ xp(75); },
  t:["Le lastre lucide sono piastre a pressione. Le scavalcate una per una, mentre nelle pareti, a un palmo dalle vostre facce, brillano le punte di cento dardi in attesa.","The shiny flags are pressure plates. You step over them one by one, while in the walls, a hand's breadth from your faces, the tips of a hundred waiting darts glint.","Las losas brillantes son placas de presión. Las pasáis una a una, mientras en las paredes, a un palmo de vuestras caras, brillan las puntas de cien dardos esperando."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"v_hall"}]};
SC.v_trap_ko = {bg:"crypt", loc:LOC_V, once(){ dmgParty(5); },
  t:["Un clic sotto lo stivale. Dalle pareti esplode una pioggia di dardi. Vi gettate a terra, ma non abbastanza in fretta: tutti siete feriti, anche se di striscio.","A click under a boot. A hail of darts bursts from the walls. You throw yourselves down, but not fast enough: you're all grazed.","Un clic bajo la bota. De las paredes estalla una lluvia de dardos. Os tiráis al suelo, pero no lo bastante rápido: todos acabáis heridos, aunque de refilón."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"v_hall"}]};
SC.v_hall = {bg:"crypt", loc:LOC_V,
  t:["La Sala dei Caduti. File di nicchie scavate nella roccia, ognuna con uno scheletro in armatura e una lama posata sul petto. Quando entrate, centinaia di orbite vuote si accendono di una luce fredda. Alcuni scheletri si alzano. In fondo alla sala, un'armatura vuota afferra la sua spada.",
     "The Hall of the Fallen. Rows of niches cut into the rock, each holding an armoured skeleton with a blade laid on its chest. As you enter, hundreds of empty sockets kindle with a cold light. Some skeletons rise. At the end of the hall, an empty suit of armour grips its sword.",
     "La Sala de los Caídos. Hileras de nichos excavados en la roca, cada uno con un esqueleto acorazado y una hoja sobre el pecho. Al entrar, cientos de cuencas vacías se encienden con una luz fría. Algunos esqueletos se alzan. Al fondo de la sala, una armadura vacía empuña su espada."],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"vault1", win:"v_altar"}]};
SC.v_altar = {bg:"shrine", loc:LOC_V,
  t:["Oltre la sala, una cappella intatta. Sull'altare arde ancora, debolissima, una fiamma dorata: forse l'ultima fiamma del sole rimasta in tutta Vesperia. Ai piedi dell'altare, una cassetta di offerte piena di monete antiche.",
     "Beyond the hall, an intact chapel. On the altar a golden flame still burns, very faintly: perhaps the last flame of the sun left in all Vesperia. At the foot of the altar, an offering box full of ancient coins.",
     "Más allá de la sala, una capilla intacta. Sobre el altar aún arde, muy débil, una llama dorada: quizá la última llama del sol que queda en toda Vesperia. Al pie del altar, una caja de ofrendas llena de monedas antiguas."],
  ch:[
    {t:["Pregare davanti alla fiamma","Pray before the flame","Rezar ante la llama"], req:()=>!has("v_prayed") && !has("v_taken"), check:{sk:"rel", dc:12, ok:"v_altar_ok", ko:"v_altar_ko"}},
    {t:["Prendere le monete","Take the coins","Coger las monedas"], req:()=>!has("v_taken") && !has("v_prayed"), go:"v_taken"},
    {t:["Proseguire","Press on","Seguir"], go:"v_puzzle"}]};
SC.v_altar_ok = {bg:"shrine", loc:LOC_V, once(){ set("v_prayed"); longRest(); xp(100); },
  t:["Vi inginocchiate. La fiamma si alza, calda come un mattino d'estate, e per un momento sentite la stanchezza scivolare via. Ferite chiuse, incantesimi rinnovati. Il marchio sulla tua mano smette di pulsare, come placato.","You kneel. The flame rises, warm as a summer morning, and for a moment you feel the weariness slip away. Wounds closed, spells renewed. The mark on your hand stops throbbing, as if soothed.","Os arrodilláis. La llama se alza, cálida como una mañana de verano, y por un momento sentís que el cansancio se desvanece. Heridas cerradas, conjuros renovados. La marca de tu mano deja de latir, como apaciguada."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"v_puzzle"}]};
SC.v_altar_ko = {bg:"shrine", loc:LOC_V, once(){ set("v_prayed"); S.party.forEach(c => c.hp = Math.min(c.maxhp, c.hp + Math.ceil(c.maxhp / 4))); },
  t:["Le parole della preghiera vi tornano confuse. La fiamma tremola ma non si alza. Vi scalda appena le mani: qualche ferita si chiude, non di più.","The words of the prayer come back jumbled. The flame flickers but does not rise. It barely warms your hands: a few wounds close, no more.","Las palabras de la oración os vuelven confusas. La llama tiembla pero no se alza. Apenas os calienta las manos: algunas heridas se cierran, nada más."],
  ch:[{t:["Proseguire","Press on","Seguir"], go:"v_puzzle"}]};
SC.v_taken = {bg:"shrine", loc:LOC_V, once(){ set("v_taken"); gold(90); },
  t:()=>cat(["Le monete sono pesanti, d'oro vecchio, coniate con un sole a sette raggi. Mentre le raccogliete, la fiamma sull'altare si spegne con un sospiro.\n\nDa qualche parte, più in basso, qualcosa si sveglia.","The coins are heavy, old gold, stamped with a seven-rayed sun. As you gather them, the flame on the altar goes out with a sigh.\n\nSomewhere further down, something wakes.","Las monedas pesan, oro viejo, acuñadas con un sol de siete rayos. Mientras las recogéis, la llama del altar se apaga con un suspiro.\n\nEn algún lugar, más abajo, algo despierta."],
    inP("ilyra") && ["Ilyra ti guarda. «Ottimo. Davvero ottimo.»","Ilyra looks at you. “Excellent. Truly excellent.”","Ilyra te mira. «Excelente. De verdad excelente.»"]),
  ch:[{t:["Proseguire","Press on","Seguir"], go:"v_puzzle"}]};
SC.v_puzzle = {bg:"crypt", loc:LOC_V,
  t:["Una porta rotonda di bronzo chiude il passaggio. Al centro, un disco solare che si può ruotare. Intorno, tre statue: una donna che si stiracchia (l'Alba), un uomo che alza la spada al cielo (il Mezzogiorno), un vecchio che si appoggia al bastone (il Tramonto). Sotto ciascuna, un incavo per il disco.\n\nSull'architrave è inciso: «Come il giorno, così il cammino.»",
     "A round bronze door blocks the passage. At its centre, a sun disc that can be turned. Around it, three statues: a woman stretching (Dawn), a man raising his sword to the sky (Noon), an old man leaning on his staff (Dusk). Beneath each, a socket for the disc.\n\nOn the lintel is carved: “As the day, so the path.”",
     "Una puerta redonda de bronce cierra el paso. En el centro, un disco solar que se puede girar. Alrededor, tres estatuas: una mujer que se despereza (el Alba), un hombre que alza la espada al cielo (el Mediodía), un anciano apoyado en su bastón (el Ocaso). Bajo cada una, un hueco para el disco.\n\nEn el dintel está grabado: «Como el día, así el camino.»"],
  ch:[
    {t:["Esaminare le statue","Examine the statues","Examinar las estatuas"], req:()=>!has("v_hint"), check:{sk:"his", dc:12, ok:"v_hint", ko:"v_hint_ko"}},
    {t:["Ruotare il disco: Tramonto, Alba, Mezzogiorno","Turn the disc: Dusk, Dawn, Noon","Girar el disco: Ocaso, Alba, Mediodía"], go:"v_puzzle_ko"},
    {t:["Ruotare il disco: Alba, Mezzogiorno, Tramonto","Turn the disc: Dawn, Noon, Dusk","Girar el disco: Alba, Mediodía, Ocaso"], go:"v_puzzle_ok"},
    {t:["Ruotare il disco: Mezzogiorno, Tramonto, Alba","Turn the disc: Noon, Dusk, Dawn","Girar el disco: Mediodía, Ocaso, Alba"], go:"v_puzzle_ko"}]};
SC.v_hint = {bg:"crypt", loc:LOC_V, once(){ set("v_hint"); xp(50); },
  t:["Sui piedistalli, sotto la polvere, ci sono dei numeri incisi in aurelico antico: uno sotto l'Alba, due sotto il Mezzogiorno, tre sotto il Tramonto. Il giorno, e il cammino, cominciano dall'alba.","On the pedestals, beneath the dust, numbers are carved in old Aurelian: one under Dawn, two under Noon, three under Dusk. The day, and the path, begin at dawn.","En los pedestales, bajo el polvo, hay números grabados en aureliano antiguo: uno bajo el Alba, dos bajo el Mediodía, tres bajo el Ocaso. El día, y el camino, empiezan al alba."],
  ch:[{t:["Continuare","Go on","Continuar"], go:"v_puzzle"}]};
SC.v_hint_ko = {bg:"crypt", loc:LOC_V, once(){ set("v_hint"); },
  t:["Le statue sono belle e antiche, ma non vi dicono niente di più di quello che già vedete.","The statues are beautiful and ancient, but they tell you nothing more than what you already see.","Las estatuas son bellas y antiguas, pero no os dicen nada más de lo que ya veis."],
  ch:[{t:["Continuare","Go on","Continuar"], go:"v_puzzle"}]};
SC.v_puzzle_ok = {bg:"crypt", loc:LOC_V, once(){ xp(150); gold(120); item("greater", 2); },
  t:["Il disco scatta tre volte e la porta rotola di lato senza un rumore. Dietro c'è una piccola camera sigillata: le offerte dei Custodi ai loro morti. Monete d'oro e due fiale di vetro soffiato, il cui liquido rosso brilla ancora.","The disc clicks three times and the door rolls aside without a sound. Behind it is a small sealed chamber: the Sunwardens' offerings to their dead. Gold coins and two vials of blown glass whose red liquid still glows.","El disco chasquea tres veces y la puerta rueda a un lado sin un ruido. Detrás hay una pequeña cámara sellada: las ofrendas de los Custodios a sus muertos. Monedas de oro y dos frascos de vidrio soplado cuyo líquido rojo aún brilla."],
  ch:[{t:["Scendere più in basso","Descend further","Bajar más"], go:"v_door"}]};
SC.v_puzzle_ko = {bg:"crypt", loc:LOC_V,
  t:["Il disco scatta, poi si blocca con uno stridio. Dalle nicchie ai lati della porta escono tre armature vuote, con le visiere accese di luce bianca. «Ladri di tombe» rimbomba una voce. «Il giorno non perdona chi ne sbaglia il corso.»","The disc clicks, then jams with a screech. From the niches beside the door step three empty suits of armour, visors lit with white light. “Grave robbers,” a voice booms. “The day does not forgive those who mistake its course.”","El disco chasquea y luego se atasca con un chirrido. De los nichos junto a la puerta salen tres armaduras vacías, con las viseras encendidas de luz blanca. «Ladrones de tumbas» retumba una voz. «El día no perdona a quien equivoca su curso.»"],
  ch:[{t:["Combattere","Fight","Luchar"], fight:"vault_guard", win:"v_door"}]};
SC.v_door = {bg:"mirror", loc:LOC_V,
  t:()=>cat(["L'ultima sala è un pozzo di ossidiana nera. Le pareti riflettono le vostre figure, deformate. Al centro, su un trono di vetro, siede un gigante d'ossidiana con una rastrelliera di lame dorate alle spalle: le Armi dei Custodi.\n\nIl gigante si alza. Il pavimento trema.","The last hall is a pit of black obsidian. The walls reflect your figures, distorted. At its centre, on a throne of glass, sits an obsidian giant with a rack of golden blades behind it: the Sunwardens' Weapons.\n\nThe giant rises. The floor shakes.","La última sala es un pozo de obsidiana negra. Las paredes reflejan vuestras figuras, deformadas. En el centro, en un trono de vidrio, se sienta un gigante de obsidiana con un armero de hojas doradas a su espalda: las Armas de los Custodios.\n\nEl gigante se alza. El suelo tiembla."],
    has("v_taken") && ["Dalle pareti escono anche ombre, attratte dall'oro che portate addosso.","Shadows seep out of the walls as well, drawn by the gold you carry.","De las paredes salen también sombras, atraídas por el oro que lleváis encima."],
    ["Il Custode d'Ossidiana è fatto di vetro: il fuoco gli fa poco, ma un buon colpo contundente potrebbe incrinarlo.","The Obsidian Warden is made of glass: fire barely harms it, but a good blunt blow might crack it.","El Guardián de Obsidiana es de vidrio: el fuego apenas le hace daño, pero un buen golpe contundente podría agrietarlo."]),
  ch:[{t:["Combattere","Fight","Luchar"], fight:()=>has("v_taken") ? "vault_boss_hard" : "vault_boss", win:"v_end"}, {t:["Ritirarsi e tornare più tardi","Withdraw and come back later","Retirarse y volver más tarde"], go:"vesperia"}]};
SC.v_end = {bg:"mirror", loc:LOC_V, once(){ set("vault_done"); xp(250); },
  t:["Il gigante si frantuma in mille schegge nere che tintinnano sul pavimento come pioggia. Sulla rastrelliera, le Armi dei Custodi brillano di una luce che non vedevate da quaranta giorni: la luce del sole.\n\nNe prendete una, la più bella. Le altre restano dove sono, per chi verrà dopo di voi.","The giant shatters into a thousand black shards that tinkle on the floor like rain. On the rack, the Sunwardens' Weapons shine with a light you haven't seen in forty days: sunlight.\n\nYou take one, the finest. The others stay where they are, for whoever comes after you.","El gigante se hace añicos en mil esquirlas negras que tintinean en el suelo como lluvia. En el armero, las Armas de los Custodios brillan con una luz que no veíais desde hacía cuarenta días: la luz del sol.\n\nTomáis una, la más bella. Las demás se quedan donde están, para quien venga después."],
  ch:[{t:["Tornare a Vesperia","Return to Vesperia","Volver a Vesperia"], go:"vesperia"}]};
